"""Additional CLI probe: actual profile, sealed/opened report and actual saved knowledge."""
from pathlib import Path
import hashlib,json,subprocess,tempfile,argparse
R=Path(__file__).resolve().parents[1];OUT=R/'Docs/Design/CommunityEconomyV2/runtime-local/report-probe'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
CS=r'''using HakutaiKagami.Core.Contracts;
static void Need(bool ok,string text){if(!ok)throw new Exception(text);}
static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Need(s.Seconds>old,"time stopped");}}
static long Day(WorldSession s,int y,int m,int d)=>(new DateOnly(y,m,d).DayNumber-DateOnly.Parse(s.DiagnosticSnapshot().EpochDate).DayNumber)*86400L;
static WorldSession Start()=>new(NewGameWorld.Create(NewGameWorld.Scenario(),[],"person:nobunaga",285,economyPolicy:CommunityEconomy.Policy));
static void Act(WorldSession s,EconomyAction action,long n,string id){var result=s.ManageCommunity(new(new(id),new("site:castle"),action,n),s.PlayerControl,s.Revision);Need(result.Code==ResultCode.Accepted,result.VisibleReason);}
var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"community-profile-"+Guid.NewGuid().ToString("N")));
var profile=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",285,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,CommunityEconomy.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);
Need(store.Read(profile.Instance).EconomyPolicy==CommunityEconomy.Policy,"profile policy missing");var normal=new WorldSession(NewCampaignStore.Build(profile));Need(normal.CommunityEconomyView()!=null&&normal.DiagnosticSnapshot().Economy==null,"normal entry missing");
var s=Start();Advance(s,Day(s,1560,10,1));Act(s,EconomyAction.CollectLevy,3000,"request:probe-levy");Advance(s,Day(s,1561,7,1));var notice=s.DiagnosticSnapshot().Communities!.Notices.Single(n=>n.Site.Value=="site:castle");var id=new EntityId(notice.Message);string body=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==id.Value).Body;
Need(s.Open(s.PlayerControl,id,s.Revision).Code==ResultCode.NotAvailable,"opened before physical receipt");Advance(s,s.Seconds+1);var visible=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id==id);Need(visible.KnownBody==null,"sealed body leaked");Act(s,EconomyAction.RelieveVillage,1000,"request:probe-aid");Need(s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==id.Value).Body==body,"report rewritten after relief");Need(s.Open(s.PlayerControl,id,s.Revision).Code==ResultCode.Accepted,"cannot open physically delivered report");string known=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id==id).KnownBody!;var payload=ContractJson.Read<CommunityReport>(System.Text.Encoding.UTF8.GetBytes(known));Need(payload.Need==1000&&payload.ObservedAt==notice.At&&payload.Site==notice.Site,"dated observation changed");Need(!known.Contains("HouseRice")&&!known.Contains("Climate"),"remote accounts leaked into letter");
s.SetPaused(true);var w=s.DiagnosticSnapshot();var saves=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"community-report-"+Guid.NewGuid().ToString("N")),w.Definitions);Need(saves.Save(s,"opened",w.WorldId).Published,"save failed");var host=new WorldSessionHost(Start());Need(host.CommitLoad(saves.Prepare("opened"),host.Current,host.Current.Revision)==ResultCode.Accepted,"load failed");var b=host.Current;Need(ContractJson.Write(s.GetActorView(s.PlayerControl)).SequenceEqual(ContractJson.Write(b.GetActorView(b.PlayerControl))),"known presentation changed after recovery");Need(b.Open(b.PlayerControl,id,b.Revision).Code==ResultCode.AlreadyAccepted,"opened again");Advance(s,s.Seconds+20);Advance(b,b.Seconds+20);Need(ContractJson.Write(s.DiagnosticSnapshot()).SequenceEqual(ContractJson.Write(b.DiagnosticSnapshot())),"future world changed after report recovery");Console.WriteLine("PASS normal profile; physical receipt; sealed/opened dated report; relief does not rewrite; real generation load; future world equality");
'''
def check():
 v=json.loads((OUT/'proof.json').read_bytes());assert v['status']=='PASSED';assert v['script']==sha(Path(__file__));assert v['core']==sha(R/'Core/bin/Debug/net8.0/HakutaiKagami.Core.dll');assert v['log']==sha(OUT/'probe.log');return v
def main():
 p=argparse.ArgumentParser();p.add_argument('--check-only',action='store_true');a=p.parse_args()
 if a.check_only:check();print('PASS report probe evidence');return
 OUT.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='community-report-probe-'));(work/'Program.cs').write_text(CS,encoding='utf-8');dll=R/'Core/bin/Debug/net8.0/HakutaiKagami.Core.dll'
 (work/'probe.csproj').write_text('<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net8.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup><ItemGroup><Reference Include="HakutaiKagami.Core"><HintPath>'+str(dll)+'</HintPath></Reference></ItemGroup></Project>')
 q=subprocess.run(['dotnet','run','--project',str(work/'probe.csproj'),'--verbosity','quiet'],capture_output=True,creationflags=subprocess.CREATE_NO_WINDOW,timeout=300);(OUT/'probe.log').write_bytes(q.stdout+q.stderr);assert q.returncode==0,(OUT/'probe.log').read_text(errors='replace')
 (OUT/'proof.json').write_text(json.dumps(dict(status='PASSED',script=sha(Path(__file__)),core=sha(dll),log=sha(OUT/'probe.log')),indent=2)+'\n');check();print('PASS actual community profile and report recovery probe')
if __name__=='__main__':main()
